@@ -343,3 +343,23 @@ async function saveSession(store: SessionStore | undefined, session: ChatSession
     log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
   }
 }
+
+// Preserves Error instances by identity and wraps other rejections with cause so onError stays typed against Error.
+function toHookError(error: unknown): Error {
+  if (error instanceof Error) return error;
+  return new Error(describeRejection(error), {cause: error});
+}
+
+function describeRejection(reason: unknown): string {
+  if (typeof reason === 'string') return reason;
+  return serializedOrNull(reason) ?? String(reason);
+}
+
+function serializedOrNull(value: unknown): string | null {
+  try {
+    const serialized: string | undefined = JSON.stringify(value);
+    return serialized ?? null;
+  } catch {
+    return null;
+  }
+}
